func (t WsServerMessage) Discriminator() (string, error) {
	var discriminator struct {
		Discriminator string `json:"type"`
	}
	err := json.Unmarshal(t.union, &discriminator)
	return discriminator.Discriminator, err
}

func (t WsServerMessage) ValueByDiscriminator() (interface{}, error) {
	discriminator, err := t.Discriminator()
	if err != nil {
		return nil, err
	}
	switch discriminator {
	case "entries":
		return t.AsWsServerEntries()
	case "error":
		return t.AsWsServerError()
	case "frame":
		return t.AsWsServerFrame()
	case "index":
		return t.AsWsServerIndex()
	case "index.patch":
		return t.AsWsServerIndexPatch()
	case "live.reset":
		return t.AsWsServerLiveReset()
	case "orb":
		return t.AsWsServerOrb()
	case "pong":
		return t.AsWsServerPong()
	case "res":
		return t.AsWsServerRes()
	case "thread.snapshot":
		return t.AsWsServerThreadSnapshot()
	case "ui.resolved":
		return t.AsWsServerUIResolved()
	default:
		return nil, errors.New("unknown discriminator value: " + discriminator)
	}
}

func (t WsServerMessage) MarshalJSON() ([]byte, error) {
	b, err := t.union.MarshalJSON()
	return b, err
}

func (t *WsServerMessage) UnmarshalJSON(b []byte) error {
	err := t.union.UnmarshalJSON(b)
	return err
}

// ServerInterface represents all server handlers.
type ServerInterface interface {
	// ListAgentConfigFiles omp-home 文件列表
	// (GET /api/v1/agent-config/files)
	ListAgentConfigFiles(w http.ResponseWriter, r *http.Request)
	// DeleteAgentConfigFile 删除文件
	// (DELETE /api/v1/agent-config/files/{path})
	DeleteAgentConfigFile(w http.ResponseWriter, r *http.Request, path AgentConfigPath)
	// GetAgentConfigFile 读取文件原文（`models.yml` 返回的是密钥已替换为 `${oryn:secret:…}` 的模板）
	// (GET /api/v1/agent-config/files/{path})
	GetAgentConfigFile(w http.ResponseWriter, r *http.Request, path AgentConfigPath)
	// PutAgentConfigFile 写入文件（`models.yml` 会做 C5 的密钥抽取）
	// (PUT /api/v1/agent-config/files/{path})
	PutAgentConfigFile(w http.ResponseWriter, r *http.Request, path AgentConfigPath, params PutAgentConfigFileParams)
	// ImportAgentConfig 导入 tar 包（`oryn config push` 使用）
	// (POST /api/v1/agent-config/import)
	ImportAgentConfig(w http.ResponseWriter, r *http.Request)
	// AuthLoginBegin 开始 Passkey 登录（可发现凭据）
	// (POST /api/v1/auth/login/begin)
	AuthLoginBegin(w http.ResponseWriter, r *http.Request)
	// AuthLoginFinish 完成 Passkey 登录
	// (POST /api/v1/auth/login/finish)
	AuthLoginFinish(w http.ResponseWriter, r *http.Request)
	// AuthLogout 注销当前网页会话
	// (POST /api/v1/auth/logout)
	AuthLogout(w http.ResponseWriter, r *http.Request)
	// AuthRecovery 用恢复码换取「重新注册 Passkey」的一次性会话
	// (POST /api/v1/auth/recovery)
	AuthRecovery(w http.ResponseWriter, r *http.Request)
	// AuthSetupBegin 开始注册 Passkey
	// (POST /api/v1/auth/setup/begin)
	AuthSetupBegin(w http.ResponseWriter, r *http.Request)
	// AuthSetupFinish 完成注册 Passkey
	// (POST /api/v1/auth/setup/finish)
	AuthSetupFinish(w http.ResponseWriter, r *http.Request)
	// GetBlob 下载 blob（转录中 `blob:sha256:<hex>` 引用的图片等）
	// (GET /api/v1/blobs/{sha256})
	GetBlob(w http.ResponseWriter, r *http.Request, sha256 Sha256)
	// ListDevices 设备列表
	// (GET /api/v1/devices)
	ListDevices(w http.ResponseWriter, r *http.Request)
	// DevicePairApprove 在网页上批准配对（需网页会话）
	// (POST /api/v1/devices/pair/approve)
	DevicePairApprove(w http.ResponseWriter, r *http.Request)
	// DevicePairPoll 发起方轮询配对结果（免鉴权，靠 verifier）
	// (POST /api/v1/devices/pair/poll)
	DevicePairPoll(w http.ResponseWriter, r *http.Request)
	// DevicePairStart 发起设备配对（免鉴权）
	// (POST /api/v1/devices/pair/start)
	DevicePairStart(w http.ResponseWriter, r *http.Request)
	// GetDevicePairing 查看待批准的配对请求（需网页会话）
	// (GET /api/v1/devices/pair/{code})
	GetDevicePairing(w http.ResponseWriter, r *http.Request, code string)
	// RevokeDevice 吊销设备（之后该令牌请求返回 401）
	// (DELETE /api/v1/devices/{id})
	RevokeDevice(w http.ResponseWriter, r *http.Request, id DeviceIDPath)
	// GetMe 当前身份
	// (GET /api/v1/me)
	GetMe(w http.ResponseWriter, r *http.Request)
	// ListOrbs orb 列表
	// (GET /api/v1/orbs)
	ListOrbs(w http.ResponseWriter, r *http.Request, params ListOrbsParams)
	// DeleteOrb 删除 orb（先 shutdown 再 delete；其线程保留条目，`orbId` 置空）
	// (DELETE /api/v1/orbs/{id})
	DeleteOrb(w http.ResponseWriter, r *http.Request, id OrbIDPath)
	// GetOrb orb 详情
	// (GET /api/v1/orbs/{id})
	GetOrb(w http.ResponseWriter, r *http.Request, id OrbIDPath)
	// GetOrbMetrics orb 资源采样（按 `step` 降采样，取窗口内均值；网络字节取窗口末值）
	// (GET /api/v1/orbs/{id}/metrics)
	GetOrbMetrics(w http.ResponseWriter, r *http.Request, id OrbIDPath, params GetOrbMetricsParams)
	// PauseOrb 手动冻结或停机
	// (POST /api/v1/orbs/{id}/pause)
	PauseOrb(w http.ResponseWriter, r *http.Request, id OrbIDPath)
	// ResumeOrb 唤醒 orb（`frozen` / `stopped` / `failed` → `waking`）
	// (POST /api/v1/orbs/{id}/resume)
	ResumeOrb(w http.ResponseWriter, r *http.Request, id OrbIDPath)
	// ListProjects 项目列表
	// (GET /api/v1/projects)
	ListProjects(w http.ResponseWriter, r *http.Request, params ListProjectsParams)
	// CreateProject 新建项目
	// (POST /api/v1/projects)
	CreateProject(w http.ResponseWriter, r *http.Request)
	// DeleteProject 删除项目（其线程保留，`projectId` 置空）
	// (DELETE /api/v1/projects/{id})
	DeleteProject(w http.ResponseWriter, r *http.Request, id ProjectIDPath)
	// GetProject 项目详情
	// (GET /api/v1/projects/{id})
	GetProject(w http.ResponseWriter, r *http.Request, id ProjectIDPath)
	// UpdateProject 修改项目
	// (PATCH /api/v1/projects/{id})
	UpdateProject(w http.ResponseWriter, r *http.Request, id ProjectIDPath)
	// ListProviders provider 列表
	// (GET /api/v1/providers)
	ListProviders(w http.ResponseWriter, r *http.Request)
	// CreateProvider 新建 provider（令牌只显示一次）
	// (POST /api/v1/providers)
	CreateProvider(w http.ResponseWriter, r *http.Request)
	// DeleteProvider 删除（停用）provider，其令牌立即失效
	// (DELETE /api/v1/providers/{id})
	DeleteProvider(w http.ResponseWriter, r *http.Request, id ProviderIDPath)
	// ListSecrets 密钥列表（仅名称与元数据）
	// (GET /api/v1/secrets)
	ListSecrets(w http.ResponseWriter, r *http.Request)
	// DeleteSecret 删除密钥
	// (DELETE /api/v1/secrets/{name})
	DeleteSecret(w http.ResponseWriter, r *http.Request, name SecretNamePath)
	// PutSecret 写入密钥
	// (PUT /api/v1/secrets/{name})
	PutSecret(w http.ResponseWriter, r *http.Request, name SecretNamePath)
	// GetOrbStats orb 生命周期统计（由 `orb_events` 计算）
	// (GET /api/v1/stats/orbs)
	GetOrbStats(w http.ResponseWriter, r *http.Request, params GetOrbStatsParams)
	// GetUsageStats 模型用量分组聚合
	// (GET /api/v1/stats/usage)
	GetUsageStats(w http.ResponseWriter, r *http.Request, params GetUsageStatsParams)
	// ListThreads 线程列表
	// (GET /api/v1/threads)
	ListThreads(w http.ResponseWriter, r *http.Request, params ListThreadsParams)
	// CreateThread 新建线程
	// (POST /api/v1/threads)
	CreateThread(w http.ResponseWriter, r *http.Request)
	// DeleteThread 删除线程（停止其 agent，删除条目）
	// (DELETE /api/v1/threads/{id})
	DeleteThread(w http.ResponseWriter, r *http.Request, id ThreadIDPath)
	// GetThread 线程详情
	// (GET /api/v1/threads/{id})
	GetThread(w http.ResponseWriter, r *http.Request, id ThreadIDPath)
	// UpdateThread 修改线程（改名时控制面同时向 agent 发 `set_session_name`）
	// (PATCH /api/v1/threads/{id})
	UpdateThread(w http.ResponseWriter, r *http.Request, id ThreadIDPath)
	// ListThreadEntries 分页读取已复制条目（按 `seq` 升序）
	// (GET /api/v1/threads/{id}/entries)
	ListThreadEntries(w http.ResponseWriter, r *http.Request, id ThreadIDPath, params ListThreadEntriesParams)
	// ForkThread fork 线程（共用 orb 或连环境分叉）
	// (POST /api/v1/threads/{id}/fork)
	ForkThread(w http.ResponseWriter, r *http.Request, id ThreadIDPath)
	// WakeThread 唤醒线程所在 orb（异步）
	// (POST /api/v1/threads/{id}/wake)
	WakeThread(w http.ResponseWriter, r *http.Request, id ThreadIDPath)
	// CreateWsTicket 签发 WebSocket 票据（一次性，30 秒有效）
	// (POST /api/v1/ws-ticket)
	CreateWsTicket(w http.ResponseWriter, r *http.Request)
	// GetHealthz 健康检查
	// (GET /healthz)
	GetHealthz(w http.ResponseWriter, r *http.Request)
	// ProviderBye provider 实例下线，释放租约
	// (POST /provider/v1/bye)
	ProviderBye(w http.ResponseWriter, r *http.Request)
	// ProviderHello provider 实例上线并取得租约
	// (POST /provider/v1/hello)
	ProviderHello(w http.ResponseWriter, r *http.Request)
	// ProviderClaimJob 长轮询认领任务（同时续租）
	// (POST /provider/v1/jobs/claim)
	ProviderClaimJob(w http.ResponseWriter, r *http.Request)
	// ProviderCompleteJob 上报任务结果
	// (POST /provider/v1/jobs/{id}/complete)
	ProviderCompleteJob(w http.ResponseWriter, r *http.Request, id JobID)
}

